package com.payment.rtgsimps.config;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.context.annotation.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.AnonymousAuthenticationFilter;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Configuration public class SecurityConfig {
 @Bean @Profile("!local & !test") SecurityFilterChain production(HttpSecurity h)throws Exception{h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/actuator/health/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(Customizer.withDefaults()));return h.build();}
 @Bean @Profile({"local","test"}) SecurityFilterChain local(HttpSecurity h)throws Exception{h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.anyRequest().permitAll()).addFilterBefore(new LocalPrincipalFilter(),AnonymousAuthenticationFilter.class);return h.build();}
 static class LocalPrincipalFilter extends OncePerRequestFilter{protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws ServletException,IOException{SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("local-customer","N/A",List.of(new SimpleGrantedAuthority("ROLE_USER"))));c.doFilter(q,s);}}
}
